    def _reap(self) -> bool:
        """Reap the child if it has exited.  Return True if still running."""
        if self._dead or self.pid is None:
            return False
        try:
            pid, status = os.waitpid(self.pid, os.WNOHANG)
        except ChildProcessError:
            self._dead = True
            return False
        if pid == self.pid:
            self._dead = True
            self._exit_status = os.waitstatus_to_exitcode(status)
            return False
        return True

    def is_alive(self) -> bool:
        """Return True while the shell process is still running."""
        if self._closed:
            return False
        return self._reap()

    @property
    def exit_status(self) -> Optional[int]:
        """Exit code of the shell (None while it is still running)."""
